<?php require_once "includes/db.php";$msg="";$err="";$properties=$conn->query("SELECT id,name FROM properties ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);
if($_SERVER["REQUEST_METHOD"]==="POST"){$pid=(int)($_POST["property_id"]??0);$name=trim($_POST["full_name"]??"");$email=trim($_POST["email"]??"");$phone=trim($_POST["phone"]??"");$in=$_POST["check_in"]??"";$out=$_POST["check_out"]??"";$guests=(int)($_POST["guests"]??0);if(!$pid||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$phone||!$in||!$out||$guests<1||$out<=$in)$err="تکایە زانیارییەکان بە دروستی پڕ بکەرەوە.";else{$stmt=$conn->prepare("INSERT INTO bookings(property_id,full_name,email,phone,check_in,check_out,guests) VALUES(?,?,?,?,?,?,?)");$stmt->execute([$pid,$name,$email,$phone,$in,$out,$guests]);$msg="داواکاری حجزکردنت بە سەرکەوتوویی نێردرا.";}}$selected=(int)($_GET["id"]??0);$page_title="حجزکردن";include "includes/header.php"; ?>
<section class="section"><div class="container"><h1 class="section-title">حجزکردنی شوێن</h1><div class="form-box"><?php if($msg): ?><p class="success"><?= $msg ?></p><?php endif; ?><?php if($err): ?><p class="error"><?= $err ?></p><?php endif; ?><form method="POST"><div class="form-group"><label>شوێن</label><select name="property_id" required><option value="">هەڵبژێرە</option><?php foreach($properties as $p): ?><option value="<?= $p["id"] ?>" <?= $selected==$p["id"]?"selected":"" ?>><?= htmlspecialchars($p["name"]) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>ناوی تەواو</label><input name="full_name" required></div><div class="form-group"><label>ئیمەیڵ</label><input type="email" name="email" required></div><div class="form-group"><label>مۆبایل</label><input name="phone" required></div><div class="form-group"><label>بەرواری هاتن</label><input type="date" name="check_in" required></div><div class="form-group"><label>بەرواری ڕۆیشتن</label><input type="date" name="check_out" required></div><div class="form-group"><label>ژمارەی میوانان</label><input type="number" name="guests" min="1" required></div><button class="btn">ناردنی داواکاری</button></form></div></div></section><?php include "includes/footer.php"; ?>